const p = $input.item.json;

const coverSourceUrl = p.media_url || null;
const status = coverSourceUrl ? 'OK' : 'SEM_URL';

return {
  json: {
    post_id:          p.id,
    username:         'costurandosucesso',
    media_type:       p.media_type || 'DESCONHECIDO',
    permalink:        p.permalink || null,
    timestamp:        p.timestamp || null,
    thumbnail_url:    p.thumbnail_url || null,
    media_url:        p.media_url || null,
    cover_source_url: coverSourceUrl,
    cover_strategy:   'IMAGE → media_url',
    status:           status,
    erro:             p.error ? JSON.stringify(p.error) : null
  }
};

const p = $input.item.json;

// Reels/Vídeos: thumbnail_url é mais estável que media_url
const coverSourceUrl = p.thumbnail_url || p.media_url || null;
const status = coverSourceUrl ? 'OK' : 'SEM_URL';

return {
  json: {
    post_id:          p.id,
    username:         'eduardocristianoriginal',
    media_type:       p.media_type || 'DESCONHECIDO',
    permalink:        p.permalink || null,
    timestamp:        p.timestamp || null,
    thumbnail_url:    p.thumbnail_url || null,
    media_url:        p.media_url || null,
    cover_source_url: coverSourceUrl,
    cover_strategy:   'VIDEO → thumbnail_url || media_url',
    status:           status,
    erro:             p.error ? JSON.stringify(p.error) : null
  }
};

const p = $input.item.json;

// Carrossel: primeiro filho determina a capa
const firstChild = p.children?.data?.[0] || null;
let coverSourceUrl = null;
let coverStrategy  = 'CAROUSEL → nenhum filho encontrado';
let firstChildInfo = null;

if (firstChild) {
  firstChildInfo = {
    child_id:        firstChild.id,
    child_media_type: firstChild.media_type,
    child_media_url: firstChild.media_url || null,
    child_thumb_url: firstChild.thumbnail_url || null
  };

  if (firstChild.media_type === 'VIDEO') {
    coverSourceUrl = firstChild.thumbnail_url || firstChild.media_url || null;
    coverStrategy  = 'CAROUSEL → filho[0] é VIDEO → thumbnail_url || media_url';
  } else {
    // IMAGE ou tipo desconhecido
    coverSourceUrl = firstChild.media_url || null;
    coverStrategy  = 'CAROUSEL → filho[0] é IMAGE → media_url';
  }

  // Fallback: media_url do próprio álbum
  if (!coverSourceUrl) {
    coverSourceUrl = p.media_url || null;
    coverStrategy  += ' (fallback: media_url do álbum)';
  }
}

const totalFilhos = p.children?.data?.length || 0;
const status = coverSourceUrl ? 'OK' : 'SEM_URL';

return {
  json: {
    post_id:          p.id,
    username:         'eduardocristianoriginal',
    media_type:       p.media_type || 'DESCONHECIDO',
    permalink:        p.permalink || null,
    timestamp:        p.timestamp || null,
    thumbnail_url:    p.thumbnail_url || null,
    media_url:        p.media_url || null,
    cover_source_url: coverSourceUrl,
    cover_strategy:   coverStrategy,
    total_filhos:     totalFilhos,
    primeiro_filho:   firstChildInfo,
    status:           status,
    erro:             p.error ? JSON.stringify(p.error) : null
  }
};

const items = $input.all();

const ok     = items.filter(i => i.json.status === 'OK').length;
const semUrl = items.filter(i => i.json.status === 'SEM_URL').length;
const erros  = items.filter(i => i.json.erro).length;

// Resumo por post (sem expor tokens ou URLs internas)
const detalhes = items.map(i => {
  const j = i.json;
  return {
    post_id:          j.post_id,
    username:         j.username,
    media_type:       j.media_type,
    cover_strategy:   j.cover_strategy,
    cover_disponivel: !!j.cover_source_url,
    thumbnail_url_ok: !!j.thumbnail_url,
    media_url_ok:     !!j.media_url,
    total_filhos:     j.total_filhos ?? null,
    primeiro_filho_tipo: j.primeiro_filho?.child_media_type ?? null,
    primeiro_filho_ok:   j.primeiro_filho ? !!j.primeiro_filho.child_media_url || !!j.primeiro_filho.child_thumb_url : null,
    status:           j.status,
    erro:             j.erro || null
  };
});

return {
  json: {
    poc_summary: {
      total:    items.length,
      ok:       ok,
      sem_url:  semUrl,
      com_erro: erros,
      resultado_geral: ok === items.length ? 'APROVADO — todas as capas disponíveis' : (erros > 0 ? 'ERRO — verificar campos erro' : 'PARCIAL — algumas capas ausentes')
    },
    detalhes: detalhes
  }
};
